-- HPFFL Archives — seed data, generated from hpffl-data.js and photos.js.
-- Run after schema.sql. Idempotent: re-running updates rows in place.

on conflict (id) do update set
  name = excluded.name, active = excluded.active, first_season = excluded.first_season,
  last_season = excluded.last_season, league_seasons = excluded.league_seasons, era = excluded.era,
  owners = excluded.owners, former_owners = excluded.former_owners,
  former_names = excluded.former_names, notes = excluded.notes;

on conflict (year) do update set
  era = excluded.era, teams = excluded.teams, games = excluded.games,
  champ_franchise_id = excluded.champ_franchise_id, note = excluded.note;

on conflict (franchise_id, year) do update set
  era = excluded.era, w = excluded.w, l = excluded.l, t = excluded.t,
  pw = excluded.pw, pg = excluded.pg, champ = excluded.champ, conf = excluded.conf, div = excluded.div,
  dw = excluded.dw, dl = excluded.dl, dt = excluded.dt,
  pf = excluded.pf, pa = excluded.pa, ppf = excluded.ppf, ppa = excluded.ppa,
  potw = excluded.potw, totw = excluded.totw, mlw = excluded.mlw, mla = excluded.mla,
  cbl = excluded.cbl, cba = excluded.cba, updated_at = now();

-- Photos. storage_path defaults to the filename inside the bucket.
with p as (
  on conflict (file) do update set
    storage_path = excluded.storage_path, year = excluded.year,
    caption = excluded.caption, sort = excluded.sort
  returning id
)
select p.id, v.fid::uuid, v.s from p, (values
  ('ae8c1939-0b4c-4958-9a30-83633f0721d7', 0),
  ('600435ba-92a2-4097-b7ea-8cef7370e173', 1),
  ('607b4983-ae36-41ff-bb12-b2b23d41bb21', 2),
  ('9ce25e3d-f68e-43ce-8000-4ebcf6ef6793', 3)
) as v(fid, s) where v.fid is not null
on conflict (photo_id, franchise_id) do update set sort = excluded.sort;
